import {ShieldCheckIcon, CheckIcon} from '@primer/octicons-react'
import {Button, Checkbox, FormControl, Heading, Label, Link, Spinner, TextInput} from '@primer/react'
import CircleOcticon from '@github-ui/circle-octicon'
import {Dialog, Banner} from '@primer/react/experimental'
import {
  ReportResult,
  showAIAssistedRemediationGuidance,
  type Alert,
  type ReportTokenResponse,
  type Validation,
} from '../../../types/alert-types'
import {useContext, useEffect, useState} from 'react'
import {useCurrentUser} from '@github-ui/current-user'
import type {Repository} from '../../../types/repo-types'
import {useErrorContext} from '../../shared/ErrorContext'
import {verifiedFetch} from '@github-ui/verified-fetch'
import {secretScanningTokenReportPath} from '../../../paths'
import {useAnalytics} from '@github-ui/use-analytics'
import {useQuery} from '@github-ui/react-query'
import {verificationStatusActive} from '../../shared/VerificationStatus'
import {TimelineContext} from '../../shared/TimelineContext'
import {BetaLabel} from '@github-ui/lifecycle-labels/beta'
import {isFeatureEnabled} from '@github-ui/feature-flags'

export function Report({
  alert,
  repository,
  setValidationDetails,
  validationDetails,
}: {
  alert: Alert
  repository: Repository
  setValidationDetails: (verification: Validation) => void
  validationDetails: Validation
}) {
  const showNewAIRemediationSteps = showAIAssistedRemediationGuidance(alert)
  const reportUrl = secretScanningTokenReportPath(repository.owner_display_login, repository.name, alert.number)
  const errorContext = useErrorContext()
  const [showConfirmDialog, setShowConfirmDialog] = useState(false)
  const [confirmActionText, setConfirmActionText] = useState('')
  const [reportingComplete, setReportingComplete] = useState(alert.is_reported)
  const [userConfirmedNotice, setUserConfirmedNotice] = useState(false)
  const [userConfirmedReachout, setUserConfirmedReachout] = useState(false)
  const {sendAnalyticsEvent} = useAnalytics()
  const {signalTimelineRefetch} = useContext(TimelineContext)
  const currentUser = useCurrentUser()
  const lifecycleLabelNameEnabled = isFeatureEnabled('lifecycle_label_name_updates')

  const closeDialog = () => {
    setConfirmActionText('')
    setShowConfirmDialog(false)
    setUserConfirmedNotice(false)
    setUserConfirmedReachout(false)
  }

  const allowConfirmation =
    confirmActionText.toLowerCase() === currentUser?.login?.toLowerCase() &&
    userConfirmedNotice &&
    userConfirmedReachout

  useEffect(() => {
    if (isOneClickReportable(validationDetails)) {
      sendAnalyticsEvent('secret_scanning_alert.report_shown', 'REPORT_COMPONENT', {
        category: 'remediation',
        action: 'report_shown',
        label: 'report_token',
      })
    }
    // eslint-disable-next-line react-hooks/react-compiler
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  const onReportClicked = () => {
    handleSubmitReport()
    closeDialog()
  }

  const {isLoading, refetch: reportToken} = useQuery({
    queryKey: ['secret-scanning', 'alert', alert.number, 'validity', reportUrl],
    // eslint-disable-next-line @tanstack/query/no-void-query-fn
    queryFn: async (): Promise<ReportTokenResponse | undefined> => {
      const result = await verifiedFetch(reportUrl, {
        method: 'put',
      })
      if (!result.ok) {
        const errorText = await result.text()
        throw new Error(errorText)
      }
      const updatedValidity = await result.json()
      if (!updatedValidity.data) {
        throw new Error('Error reporting token')
      }
      return updatedValidity.data as ReportTokenResponse
    },
    enabled: false,
    retry: false,
  })

  const sendAnalyticsEventReportComplete = (success: boolean) => {
    const alertCreatedAt = new Date(alert.created_at)
    const now = new Date()
    const timeToRemediation = (now.getTime() - alertCreatedAt.getTime()) / (1000 * 60)
    sendAnalyticsEvent('secret_scanning_alert.report_complete', 'REPORT_COMPONENT', {
      category: 'remediation',
      action: 'report_complete',
      label: 'report_token',
      time_to_remediation: timeToRemediation,
      success: `${success}`,
    })
  }

  const handleSubmitReport = async () => {
    const {data, isError} = await reportToken()

    if (isError) {
      errorContext.showError('Error reporting token')
      sendAnalyticsEventReportComplete(false)
      return
    }

    if (data?.validation) {
      setValidationDetails(data.validation)
      signalTimelineRefetch()
    }

    if (data?.result === ReportResult.REPORT_RESULT_REVOKED) {
      setReportingComplete(true)
    } else {
      // In this case the result is unknown or already revoked (for PATv2s) or token not found (for Classic PATs)
      errorContext.showError('This token may have already been deactivated.')
    }

    if (data?.result !== ReportResult.REPORT_RESULT_UNKNOWN) {
      // Cases where we got back already revoked or token not found should be counted as success (IMO) because
      // these events capture TSS's successful response from a user's intent to report a leak.
      sendAnalyticsEventReportComplete(true)
    }
  }

  if (reportingComplete) {
    return (
      <div
        className={`${showNewAIRemediationSteps ? '' : 'border-top'} p-3`}
        data-testid="secret-scanning-report-token-success"
      >
        <div className="d-flex flex-justify-between">
          <div className="d-flex">
            <ShieldCheckIcon size={16} className="mt-1" />
            <div className="ml-2 pr-3">
              <div className="d-flex" data-testid="secret-scanning-report-token-success-heading">
                <Heading as="h3" className="f5">
                  Successfully reported secret leak to {alert.token_type_provider}
                </Heading>

                {lifecycleLabelNameEnabled ? (
                  <BetaLabel className="ml-2" feedbackUrl="https://github.com/orgs/community/discussions/139967" />
                ) : (
                  <>
                    <Label className="ml-2" variant="success">
                      Beta
                    </Label>
                    &nbsp;
                    <Link
                      className="mb-2 ml-2"
                      target="_blank"
                      href="https://github.com/orgs/community/discussions/139967"
                    >
                      Give feedback
                    </Link>
                  </>
                )}
              </div>
              <p>
                To avoid future incidents, please follow best practices for managing secrets to ensure sensitive
                information is not exposed in your repositories.
              </p>
            </div>
          </div>
          <div className="d-flex">
            <div className="pt-1 ml-3 ">
              <CircleOcticon icon={CheckIcon} size={16} className="bgColor-success-emphasis fgColor-onEmphasis" />
            </div>
            <div className="ml-1 pb-3">Sent to provider</div>
          </div>
        </div>
      </div>
    )
  }

  if (!isOneClickReportable(validationDetails)) {
    return null
  }

  return (
    <div className={`${showNewAIRemediationSteps ? '' : 'border-top'} p-3`} data-testid="secret-scanning-report-token">
      <div className="d-flex">
        <ShieldCheckIcon size={16} className="mt-1" />
        <div className="ml-2 pr-3">
          <div className="d-flex" data-testid="secret-scanning-report-token-heading">
            <Heading as="h3" className="f5">
              Report leaked secret to {alert.token_type_provider}
            </Heading>

            {lifecycleLabelNameEnabled ? (
              <BetaLabel className="ml-2" feedbackUrl="https://github.com/orgs/community/discussions/139967" />
            ) : (
              <>
                <Label className="ml-2" variant="success">
                  Beta
                </Label>
                &nbsp;
                <Link className="mb-2 ml-2" target="_blank" href="https://github.com/orgs/community/discussions/139967">
                  Give feedback
                </Link>
              </>
            )}
          </div>
          <p data-testid="secret-scanning-report-token-description">
            Let {alert.token_type_provider} know that this secret has been compromised. The secret will be treated like
            a publicly leaked secret and will be revoked. Consider first rotating the secret to prevent breaking
            workflows.
          </p>
        </div>
        {isLoading ? (
          <Button disabled leadingVisual={SmallSpinner}>
            Disclosing secret
          </Button>
        ) : (
          <Button
            data-testid="secret-scanning-report-token-action-button"
            variant="danger"
            onClick={() => setShowConfirmDialog(!showConfirmDialog)}
          >
            Report leak
          </Button>
        )}
      </div>

      {showConfirmDialog && (
        <Dialog
          title="Report token"
          onClose={closeDialog}
          footerButtons={[
            {
              form: 'secret-scanning-report-token-form',
              type: 'submit',
              buttonType: 'danger',
              content: <>I understand the consequences, report this secret</>,
              disabled: !allowConfirmation,
              className: 'width-full',
              onClick: () => onReportClicked(),
            },
          ]}
        >
          <Banner
            variant="warning"
            description={<>Unexpected bad things may happen if you don&apos;t read this!</>}
            hideTitle
            className="mb-2"
          >
            <Banner.Title />
          </Banner>
          <p data-testid="secret-scanning-report-token-dialog-instructions">
            When you report this secret to {alert.token_type_provider}, {alert.token_type_provider} will revoke this
            token.
          </p>
          <ul className="ml-4">
            <li>Revocation often leads to disruption of dependent applications and services.</li>
            <li>
              Carefully review any available token metadata, like locations or last used date, to get a sense of the
              potential blast radius for this token.
            </li>
            <li>The token owner will be notified when their token is revoked.</li>
          </ul>
          <br />
          <p>This action may be destructive. You cannot undo this action.</p>
          <form
            name="secret-scanning-report-token-form"
            onSubmit={e => {
              e.preventDefault()
              if (!allowConfirmation) {
                return
              }
              onReportClicked()
            }}
          >
            <FormControl>
              <Checkbox
                data-testid="secret-scanning-report-token-confirm-read-notice"
                onChange={() => setUserConfirmedNotice(!userConfirmedNotice)}
                checked={userConfirmedNotice}
              />
              <FormControl.Label>I have read and understand the above effects.</FormControl.Label>
            </FormControl>
            <FormControl className="mt-1">
              <Checkbox
                data-testid="secret-scanning-report-token-confirm-reachout"
                onChange={() => setUserConfirmedReachout(!userConfirmedReachout)}
                checked={userConfirmedReachout}
              />
              <FormControl.Label>
                I have reached out to the token owner if possible to let them know that I&apos;ll be reporting the
                token.
              </FormControl.Label>
            </FormControl>
            <hr />
            <FormControl>
              <FormControl.Label>
                <div className="text-normal" data-testid="secret-scanning-report-token-confirm-instructions">
                  Type your username to confirm.
                </div>
              </FormControl.Label>
              <TextInput
                data-testid="secret-scanning-report-token-confirm-input"
                value={confirmActionText}
                onChange={e => setConfirmActionText(e.target.value)}
                className="width-full"
              />
            </FormControl>
          </form>
        </Dialog>
      )}
    </div>
  )
}

function SmallSpinner() {
  return <Spinner size="small" data-testid="secret-scanning-report-token-spinner" />
}

export function isOneClickReportable(alertValidationDetails: Validation): boolean {
  if (!alertValidationDetails.validity_last_checked) {
    return true
  }
  if (verificationStatusActive(alertValidationDetails.validity)) {
    return true
  }
  return false
}

try{ Report.displayName ||= 'Report' } catch {}
try{ SmallSpinner.displayName ||= 'SmallSpinner' } catch {}