export function AlertTimeline({timeline}: {timeline: TimelineData}) {
  const [loadAllEvents, setLoadAllEvents] = useState(false)

  function handleLoadAllClick() {
    setLoadAllEvents(true)
  }

  return <Timeline clipSidebar>{renderTimelineItems(timeline, loadAllEvents, handleLoadAllClick)}</Timeline>
}

function renderTimelineItems(timeline: TimelineData, loadAllEvents: boolean, handleLoadAllClick: () => void) {
  const timelineItems = []

  // Push the earliest events in the timeline.
  if (timeline.earliest_events.length > 0) {
    timelineItems.push(
      timeline.earliest_events.map((event: TimelineEvent, index: number) =>
        renderTimelineItem(event, `timeline-earliest-item-${index}`),
      ),
    )
  }

  // If the number of events is greater than a set limit, then show a "Load all..." button and
  // don't show hidden events until user clicks on the button.
  if (timeline.hidden_events.length > 0) {
    if (loadAllEvents) {
      timelineItems.push(
        timeline.hidden_events.map((event: TimelineEvent, index: number) =>
          renderTimelineItem(event, `timeline-hidden-item-${index}`),
        ),
      )
    } else {
      timelineItems.push(
        <div key={'load-all'} className="d-flex flex-justify-center py-4">
          <div className="d-inline-flex flex-column px-3 py-2 border rounded-2">
            <span className="mb-1 f5 text-bold fgColor-muted">
              {timeline.hidden_events.length} hidden item{timeline.hidden_events.length > 1 ? 's' : ''}
            </span>
            <Button variant="invisible" size="small" onClick={handleLoadAllClick}>
              Load all...
            </Button>
          </div>
        </div>,
      )
    }
  }

  // Push the latest events in the timeline.
  if (timeline.latest_events.length > 0) {
    timelineItems.push(
      timeline.latest_events.map((event: TimelineEvent, index: number) =>
        renderTimelineItem(event, `timeline-latest-item-${index}`),
      ),
    )
  }

  return timelineItems
}

function renderTimelineItem(event: TimelineEvent, index: string) {
  // For delegated closure opened events, append the requester reason to the action
  const closureRequestReason = event.exemption_request?.reason
    ? ` as ${resolutionText(event.exemption_request?.reason)}` || ''
    : ''

  switch (event.type) {
    case TimelineEventType.Creation:
      return (
        <TimelineItem key={index} badgeBgColor="success.emphasis" icon={<ShieldIcon className="fgColor-onEmphasis" />}>
          <TimelineItemBody event={event} action="opened this alert" isGitHubActor />
        </TimelineItem>
      )
    case TimelineEventType.Resolution:
      if (!event.resolution) return null
      if (event.resolution.type === ResolutionType.Reopened) {
        return (
          <Fragment key={index}>
            {/* NOTE - Timeline.Break needs to be a sibling with the Timeline.Item behind it */}
            {/* for the CSS sibling selector to apply correctly. */}
            <Timeline.Break className={`${styles.timelineBreak}`} />
            <TimelineItem badgeBgColor="success.emphasis" icon={<SyncIcon className="fgColor-onEmphasis" />}>
              <TimelineItemBody event={event} action="reopened this" />
            </TimelineItem>
          </Fragment>
        )
      } else {
        let badgeBgColor: string | undefined = undefined
        let icon = <ShieldSlashIcon className="fgColor-muted" />
        if (event.resolution.type === ResolutionType.Revoked) {
          badgeBgColor = 'done.emphasis'
          icon = <ShieldCheckIcon className="fgColor-onEmphasis" />
        }
        return (
          <TimelineItem key={index} badgeBgColor={badgeBgColor} icon={icon}>
            <TimelineItemBody event={event} action={`closed this as ${resolutionText(event.resolution.type)}`} />
          </TimelineItem>
        )
      }
    case TimelineEventType.Bypass:
      return (
        <TimelineItem key={index} icon={<AlertIcon className="fgColor-muted" />}>
          <TimelineItemBody event={event} action="bypassed push protection" />
        </TimelineItem>
      )
    case TimelineEventType.DelegatedBypassRequestOpened:
      return (
        <TimelineItem key={index} icon={<CommentIcon className="fgColor-muted" />}>
          <TimelineItemBody event={event} action="requested bypass privileges" />
        </TimelineItem>
      )
    case TimelineEventType.DelegatedBypassRequestApproved:
      return (
        <TimelineItem key={index} icon={<CheckCircleIcon className="fgColor-muted" />}>
          <TimelineItemBody event={event} action="approved a bypass" />
        </TimelineItem>
      )
    case TimelineEventType.ValidityChange:
      return ValidityChangeTimelineEvent({event, index})
    case TimelineEventType.Report:
      return (
        <TimelineItem key={index} icon={<ShieldCheckIcon className="fgColor-muted" />}>
          <TimelineItemBody event={event} action="reported this secret" />
        </TimelineItem>
      )
    case TimelineEventType.DelegatedClosureRequestOpened:
      return (
        <TimelineItem key={index} icon={<CommentIcon className="fgColor-muted" />}>
          <TimelineItemBody event={event} action={`requested to dismiss this${closureRequestReason}`} />
        </TimelineItem>
      )
    case TimelineEventType.DelegatedClosureRequestApproved:
      return (
        <TimelineItem key={index} icon={<CheckCircleIcon className="fgColor-muted" />}>
          <TimelineItemBody event={event} action="approved dismissal" />
        </TimelineItem>
      )
    case TimelineEventType.DelegatedClosureRequestRejected:
      return (
        <TimelineItem key={index} icon={<XIcon className="fgColor-muted" />}>
          <TimelineItemBody event={event} action="denied dismissal" />
        </TimelineItem>
      )
    case TimelineEventType.DelegatedClosureRequestCancelled:
      return (
        <TimelineItem key={index} icon={<SkipIcon className="fgColor-muted" />}>
          <TimelineItemBody event={event} action="cancelled request to dismiss" />
        </TimelineItem>
      )
    case TimelineEventType.AssignmentChanged:
      return AssignmentChangeTimelineEvent({event, index})
  }
}

function TimelineItem({
  badgeBgColor,
  icon,
  children,
}: {
  badgeBgColor?: string
  icon: React.ReactNode
  children: React.ReactNode
}) {
  return (
    <Timeline.Item className={`${styles.timelineItem}`}>
      <Timeline.Badge sx={{backgroundColor: badgeBgColor}}>{icon}</Timeline.Badge>
      <Timeline.Body>{children}</Timeline.Body>
    </Timeline.Item>
  )
}

function TimelineItemBody({
  event,
  action,
  isGitHubActor = false,
}: {
  event: TimelineEvent
  action: string
  isGitHubActor?: boolean
}) {
  const comment =
    event.resolution?.comment ||
    event.exemption_request?.requester_comment ||
    event.exemption_response?.reviewer_comment
  const payload = useRoutePayload<ShowPayload | null>()
  const errorContext = useErrorContext()
  const showClosureRequestReviewButtons =
    payload?.show_closure_request_review_buttons && event.exemption_request?.status === 'pending'
  const showClosureRequestCancelButton =
    payload?.show_closure_request_cancel_button && event.exemption_request?.status === 'pending'

  const cancelRequestMutation = useMutation({
    mutationFn: async () => {
      const repoName = payload?.repository?.name
      const closureRequestNumber = payload?.existing_closure_request_number
      const owner = payload?.repository?.owner_display_login
      const url = secretScanningUpdateClosureRequestPath(owner ?? '', repoName ?? '', closureRequestNumber ?? 0)
      const response = await reactFetchJSON(`${url}`, {
        method: 'PUT',
        body: {
          status: 'cancel',
          repository: repoName,
        },
      })

      if (!response.ok) {
        throw new Error('Error: Unable to cancel alert dismissal request')
      }
    },
    onSuccess: () => {
      window.location.reload()
    },
    onError: error => {
      errorContext.showError(error.message)
    },
  })

  return (
    <>
      <div className="d-flex flex-items-center flex-justify-between">
        <div className="d-flex flex-items-center">
          {isGitHubActor ? (
            <>
              <MarkGithubIcon />
              <span className="ml-1 text-bold">GitHub</span>
            </>
          ) : (
            <UserComponent user={event.actor} />
          )}
          <span className="ml-1">{action}</span>
          <RelativeTime className="ml-1" datetime={event.time} />
        </div>
        {event.type === TimelineEventType.DelegatedClosureRequestOpened && showClosureRequestReviewButtons && (
          <ClosureRequestReviewButtons />
        )}
        {event.type === TimelineEventType.DelegatedClosureRequestOpened && showClosureRequestCancelButton && (
          <Button
            variant="invisible"
            size="small"
            onClick={() => cancelRequestMutation.mutate()}
            loading={cancelRequestMutation.isPending}
          >
            Cancel request
          </Button>
        )}
      </div>
      {comment && (
        <div data-testid={'resolution-comment'} className={`${styles.timelineComment} d-flex flex-items-center mt-1`}>
          <CommentIcon size={12} className="ml-1 fgColor-muted v-align-middle" />
          <span className="ml-1 f6">{comment}</span>
        </div>
      )}
    </>
  )
}

function ValidityChangeTimelineEvent({event, index}: {event: TimelineEvent; index: string}) {
  const isInactive =
    event.validity?.validity === TokenVerificationStatus.TOKEN_VALIDITY_INACTIVE ||
    event.validity?.validity === TokenVerificationStatus.TOKEN_VALIDITY_REVOKED
  const isUnknown =
    event.validity?.validity === TokenVerificationStatus.TOKEN_VALIDITY_UNKNOWN ||
    event.validity?.validity === TokenVerificationStatus.TOKEN_VALIDITY_UNVERIFIABLE

  // If active, danger.fg and 'active', otherwise use the conditions below
  const iconColor = 'fgColor-onEmphasis'
  let badgeBgColor = 'danger.fg'
  let icon = <AlertIcon className={`${iconColor}`} />
  let validityText = 'GitHub verified this secret is active'
  if (isInactive) {
    badgeBgColor = 'fg.muted'
    icon = <SkipIcon className={`${iconColor}`} />
    validityText = 'GitHub verified this secret is inactive'
  }
  if (isUnknown) {
    badgeBgColor = 'attention.fg'
    icon = <AlertIcon className={`${iconColor}`} />
    validityText = 'GitHub is unable to determine the validity of this secret'
  }

  return (
    <TimelineItem key={index} badgeBgColor={badgeBgColor} icon={icon}>
      <span className="ml-1">{validityText}</span>
      <RelativeTime className="ml-1" datetime={event.time} />
    </TimelineItem>
  )
}

function AssignmentChangeTimelineEvent({event, index}: {event: TimelineEvent; index: string}) {
  const actor = event.actor
  const assignedUser = event.assignment_change?.assigned_user
  const unassignedUser = event.assignment_change?.unassigned_user

  // Check for actor assigning or un-assigning themselves without involving assignment on another user
  const isSelfAssignment = assignedUser && !unassignedUser && actor?.display_login === assignedUser.display_login
  const isSelfUnassignment = !assignedUser && unassignedUser && actor?.display_login === unassignedUser.display_login

  // Build up the content based on the assignment scenario
  let content: React.ReactNode

  if (assignedUser && unassignedUser) {
    // Both present: "actor assigned assignedUser and unassigned unassignedUser"
    content = (
      <>
        <UserComponent user={actor} />
        <p>assigned</p>
        <UserComponent user={assignedUser} />
        <p>and unassigned</p>
        <UserComponent user={unassignedUser} />
        <RelativeTime datetime={event.time} />
      </>
    )
  } else if (assignedUser && !unassignedUser) {
    if (isSelfAssignment) {
      // Self-assignment: "actor self-assigned this"
      content = (
        <>
          <UserComponent user={actor} />
          <p>self-assigned this</p>
          <RelativeTime datetime={event.time} />
        </>
      )
    } else {
      // Assignment to someone else: "actor assigned assignedUser"
      content = (
        <>
          <UserComponent user={actor} />
          <p>assigned</p>
          <UserComponent user={assignedUser} />
          <RelativeTime datetime={event.time} />
        </>
      )
    }
  } else if (!assignedUser && unassignedUser) {
    if (isSelfUnassignment) {
      // Self-unassignment: "actor removed their assignment"
      content = (
        <>
          <UserComponent user={actor} />
          <p>removed their assignment</p>
          <RelativeTime datetime={event.time} />
        </>
      )
    } else {
      // Unassignment of someone else: "actor unassigned unassignedUser"
      content = (
        <>
          <UserComponent user={actor} />
          <p>unassigned</p>
          <UserComponent user={unassignedUser} />
          <RelativeTime datetime={event.time} />
        </>
      )
    }
  }

  return (
    <TimelineItem key={index} icon={<PersonIcon />}>
      <div className="d-flex gap-1" data-testid="assignment-timeline-content">
        {content}
      </div>
    </TimelineItem>
  )
}

try{ AlertTimeline.displayName ||= 'AlertTimeline' } catch {}
try{ TimelineItem.displayName ||= 'TimelineItem' } catch {}
try{ TimelineItemBody.displayName ||= 'TimelineItemBody' } catch {}
try{ ValidityChangeTimelineEvent.displayName ||= 'ValidityChangeTimelineEvent' } catch {}
try{ AssignmentChangeTimelineEvent.displayName ||= 'AssignmentChangeTimelineEvent' } catch {}